# =========================================================================
# 2. JANIM COMPILER (Do not modify)
# =========================================================================

def export_to_janim(filepath, frame_data, timings):
    """
    Exports a flat byte array and a timing tuple to a .janim V2 file.

    Format Spec:
    - 5-byte header (JANM + frame_count)
    - Consecutive 258-byte blocks (2-byte duration + 256-byte pixel array)
    """
    frame_count = len(timings)

    # Ensure output directory exists if a path is provided
    output_dir = os.path.dirname(filepath)
    if output_dir:
        os.makedirs(output_dir, exist_ok=True)

    with open(filepath, 'wb') as f:
        # 1. Write the 5-byte V2 header
        f.write(b'JANM')
        f.write(bytes([frame_count]))

        # 2. Interleave and write the duration and frame data
        for i in range(frame_count):
            duration_ms = timings[i]

            # Write 2-byte duration (16-bit unsigned little-endian)
            f.write(duration_ms.to_bytes(2, byteorder='little', signed=False))

            # Extract and write the 256 bytes of pixel data for this specific frame
            start_idx = i * 256
            end_idx = start_idx + 256
            f.write(frame_data[start_idx:end_idx])

    print(f"✅ Successfully generated: {filepath}")
    print(f"   Frames: {frame_count}")
    print(f"   Timings (ms): {timings}")

if __name__ == "__main__":
    # Specify the output file name
    output_filename = "cat_idle.janim"

    print(f"Compiling {output_filename}...")
    export_to_janim(output_filename, ANIMATION_DATA, TIMING_DATA)
